import java.util.*;

public class LongestIncreasingSubsequence {

    // ===== 解法 1：DP O(n²) =====
    public int lengthOfLIS_DP(int[] nums) {
        int n = nums.length;
        int[] dp = new int[n];
        int[] prev = new int[n]; // 前驱下标，用于输出序列
        Arrays.fill(dp, 1);
        Arrays.fill(prev, -1);

        int maxLen = 0, maxIdx = 0;
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < i; j++) {
                if (nums[j] < nums[i] && dp[j] + 1 > dp[i]) {
                    dp[i] = dp[j] + 1;
                    prev[i] = j;
                }
            }
            if (dp[i] > maxLen) {
                maxLen = dp[i];
                maxIdx = i;
            }
        }

        // 回溯输出一个 LIS
        List<Integer> lis = new ArrayList<>();
        for (int i = maxIdx; i >= 0; i = prev[i]) {
            lis.add(nums[i]);
        }
        Collections.reverse(lis);
        // lis 即为一个最长递增子序列

        return maxLen;
    }

    // ===== 解法 2：贪心 + 二分 O(n log n) =====
    public int lengthOfLIS_BinarySearch(int[] nums) {
        int[] tails = new int[nums.length];
        int size = 0;
        for (int x : nums) {
            int left = 0, right = size;
            while (left < right) {
                int mid = left + (right - left) / 2;
                if (tails[mid] < x) left = mid + 1;
                else right = mid;
            }
            tails[left] = x;
            if (left == size) size++;
        }
        return size;
    }
}
